def _drain_output(self, first_timeout: float) -> None:
    if self._master_fd < 0:
        return

    # Stop after a bounded amount of data.  A program that continuously
    # writes (for example, ``yes``) must not keep this method from
    # returning just because the PTY is always readable.
    max_chunks = 256
    chunks_read = 0
    timeout = first_timeout
    while chunks_read < max_chunks:
        try:
            readable, _, _ = select.select([self._master_fd], [], [], timeout)
        except (OSError, ValueError):
            return
        timeout = 0.0
        if not readable:
            return
        try:
            chunk = os.read(self._master_fd, 4096)
        except BlockingIOError:
            continue
        except OSError as error:
            if error.errno == errno.EIO:
                self._reap_if_exited()
                return
            return
        if not chunk:
            self._reap_if_exited()
            return
        self._output.extend(chunk)
        chunks_read += 1
